/**
 * Blank Harel Tour & Care application forms (edition 06/2025, Hebrew and English) and the Heebo font,
 * embedded so the Edge function always has them (binary sidecar files are often left out of deploys).
 */
export const TOUR_CARE_EN_BASE64 = "";
export const TOUR_CARE_HE_BASE64 = "";
export const HEEBO_FONT_BASE64 = "";

export function decodeBase64(b64: string): Uint8Array {
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}
